/usr/bin/bash -lc 'set -euo pipefail
count_fastq_records() {
  gzip -cd "$1" | awk '"'
    function fail(msg){print msg > \"/dev/stderr\"; bad=1; exit 1}
    state==0 { if ("'$0 !~ /''^@/) fail("expected FASTQ header"); state=1; seqlen=0; next }
    state==1 { if ($0 ~ /''^'"\\+/) { state=2; quallen=0; next } seqlen += length("'$0); next }
    state==2 { quallen += length($0); if (quallen > seqlen) fail("quality longer than sequence"); if (quallen == seqlen) { n++; state=0 } next }
    END { if (bad || state != 0 || n < 1) exit 1; print n }
  '"'
}
for pair in SRR35763863 SRR35763874; do
  f=\"final_answer/reads/"'${pair}_1.fastq.gz"
  r="final_answer/reads/${pair}_2.fastq.gz"
  nf=$(count_fastq_records "$f")
  nr=$(count_fastq_records "$r")
  diff -q '"\\
    <(gzip -cd \""'$f" | awk '"'state==0 {if("'$0 !~ /''^@/) exit 1; id=$0; sub(/''^@/,"",id); sub(/'"\\/[12]([[:space:]]|"'$)/,"",id); state=1; next} state==1 {if($0 ~ /''^'"\\+/){state=2; q=0; next} next} state==2 {q+=length("'$0); if(q==length(seq)){state=0}; next}'"' ) \\
    <(gzip -cd \""'$r" | awk '"'state==0 {if("'$0 !~ /''^@/) exit 1; id=$0; sub(/''^@/,"",id); sub(/'"\\/[12]([[:space:]]|"'$)/,"",id); state=1; next} state==1 {if($0 ~ /''^'"\\+/){state=2; q=0; next} next} state==2 {q+=length("'$0); if(q==length(seq)){state=0}; next}'"' ) || true
  printf '%s\\tforward_records=%s\\treverse_records=%s\\n' \""'$pair" "$nf" "$nr"
done'
